  if(!list.length)return `<div class="empty"><div class="empty-icon">‚ñ§</div><h3>${state.trucks.length?'Nenhum caminh√£o neste per√≠odo':'Sua primeira quinzena come√ßa aqui'}</h3><p>${state.trucks.length?'Ajuste o m√™s ou a fazenda para ver os caminh√µes contratados.':'Cadastre uma placa, informe o valor mensal e a data de in√≠cio. Ou use os exemplos para conhecer o controle.'}</p><div class="actions" style="justify-content:center"><button class="btn primary" data-action="new-truck">+ Cadastrar caminh√£o</button>${!state.trucks.length?'<button class="btn" data-action="demo">Testar com exemplos</button>':''}</div></div>`;
  return `<div class="table-wrap"><table><thead><tr><th>CAMINH√ÉO / MOTORISTA</th><th>FAZENDA</th><th class="num">DIAS NO PER√çODO</th><th class="num">DESCONTOS</th><th class="num">VALOR L√çQUIDO</th><th>SITUA√á√ÉO</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td><span class="plate">${e(r.plate)}</span><span class="secondary">${e(r.driver)}</span></td><td>${e(r.farmName)}<span class="secondary">${e(r.carrier)}</span></td><td class="num">${r.eligibleDays}<span class="secondary">${dateLabel(r.start).slice(0,5)} a ${dateLabel(r.end).slice(0,5)}</span></td><td class="num discount-color">${r.discount?money(r.discount):'‚Äî'}<span class="secondary">${r.discount?[r.discountDays?r.discountDays+' dia(s)':'',amountDiscountTotal(r)?'Por valor':''].filter(Boolean).join(' + '):'Sem desconto'}</span></td><td class="num value">${money(r.net)}<span class="secondary">${r.payableDays} dia(s) a pagar</span></td><td>${badge(r)}${r.requestId&&!r.paid?'<span class="secondary">Solicitado √† transportadora</span>':''}</td><td><button class="btn small ghost" data-action="detail" data-id="${e(r.truckId)}">Detalhes</button></td></tr>`).join('')}</tbody></table></div>`;
