const normalizeActivityPlate=value=>String(value||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
function reconciliationActivities(){
 const trucks=(isCarrier()?cteTrucks:state.trucks).filter(truck=>!truck.sample),byId=new Map(trucks.map(truck=>[truck.id,truck])),families=new Map();
 for(const truck of trucks){let root=truck,seen=new Set();while(root.transferIn?.fromTruckId&&byId.has(root.transferIn.fromTruckId)&&!seen.has(root.id)){seen.add(root.id);root=byId.get(root.transferIn.fromTruckId);}if(!families.has(root.id))families.set(root.id,[]);families.get(root.id).push(truck);}
 return [...families.entries()].map(([id,segments])=>{
  segments.sort((a,b)=>a.start.localeCompare(b.start));const first=segments[0],last=segments.find(segment=>!segment.transferOut)||segments.at(-1),start=segments.map(segment=>segment.start).filter(Boolean).sort()[0]||first.start,end=last.serviceEnded?.date||last.end||'',ids=new Set(segments.map(segment=>segment.id)),plate=first.plate||last.plate,normalized=normalizeActivityPlate(plate),through=end||today();
  const documents=cteDocuments.filter(document=>{if(document.truckId)return ids.has(document.truckId);const issued=document.issuedOn;if(!issued||issued<start||issued>through)return false;return normalizeActivityPlate(document.plate)===normalized;}).sort((a,b)=>a.issuedOn.localeCompare(b.issuedOn)||String(a.number).localeCompare(String(b.number),'pt-BR',{numeric:true}));
  const payments=(isCarrier()?portalRequests.filter(request=>request.status==='paid'&&ids.has(request.truckId||request.snapshot?.truckId)&&request.payment?.date).map(request=>({id:request.id,date:request.payment.date,amount:Number(request.snapshot?.net)||0,receipt:request.payment.receipt||null})):state.closings.flatMap(closing=>closing.rows.filter(row=>ids.has(row.truckId)&&row.paid).map(row=>({id:closing.id+'-'+row.truckId,date:row.paid.date,amount:Number(row.net)||0})))).sort((a,b)=>a.date.localeCompare(b.date));
  const manifested=round(documents.reduce((total,document)=>total+(Number(document.totalValue)||0),0)),paid=round(payments.reduce((total,payment)=>total+payment.amount,0));
  return {id,plate,driver:last.driver||first.driver,start,end,through,active:!end,documents,payments,manifested,paid,difference:round(paid-manifested)};
 }).sort((a,b)=>b.difference-a.difference||a.plate.localeCompare(b.plate,'pt-BR'));
}
function reconciliationView(){
 const all=reconciliationActivities(),query=(document.querySelector('#reconciliation-search')?.value||'').trim().toLocaleLowerCase('pt-BR'),activities=all.filter(item=>!query||(item.plate+' '+item.driver).toLocaleLowerCase('pt-BR').includes(query)),paid=round(activities.reduce((total,item)=>total+item.paid,0)),manifested=round(activities.reduce((total,item)=>total+item.manifested,0)),toManifest=round(activities.reduce((total,item)=>total+Math.max(item.difference,0),0)),overManifested=round(activities.reduce((total,item)=>total+Math.max(-item.difference,0),0));
 const rows=activities.map(item=>{const status=item.difference>0?`Falta manifestar ${money(item.difference)}`:item.difference<0?`CT-e acima do pago ${money(-item.difference)}`:item.paid||item.manifested?'Conferido':'Sem movimento',statusClass=item.difference>0?'amber':item.difference<0?'gray':item.paid||item.manifested?'green':'gray';return `<tr><td><strong class="plate">${e(item.plate)}</strong><span class="secondary">${e(item.driver)}</span></td><td>${dateLabel(item.start)} a ${item.active?'hoje (em atividade)':dateLabel(item.end)}</td><td class="num">${item.documents.length}<span class="secondary">${money(item.manifested)}</span></td><td class="num value">${money(item.paid)}</td><td><span class="badge ${statusClass}">${e(status)}</span></td><td><button class="btn small" data-action="reconciliation-detail" data-id="${e(item.id)}">Detalhes</button></td></tr>`;}).join('');
 return head('Encontro de contas',isCarrier()?'Confira, por placa, o total pago e os CT-es manifestados durante todo o per√≠odo de atividade.':'Compare o valor pago a cada placa com os CT-es manifestados durante todo o per√≠odo de atividade.','<button class="btn" data-action="cte-refresh">Atualizar CT-es</button>','CONFER√äNCIA FISCAL')+`<div class="notice neutral"><span>O per√≠odo come√ßa no in√≠cio das atividades e vai at√© o encerramento ‚Äî ou at√© hoje, se o caminh√£o continuar ativo. A confer√™ncia re√∫ne fazendas e quinzenas, sem dividir o resultado.</span><a href="#ctes">Consultar CT-es ‚Üí</a></div><div class="metric-grid reconciliation-metrics"><div class="metric"><div class="metric-label">Total pago √†s placas</div><div class="metric-value money">${money(paid)}</div></div><div class="metric"><div class="metric-label">CT-es manifestados</div><div class="metric-value money">${money(manifested)}</div></div><div class="metric featured"><div class="metric-label">Falta manifestar</div><div class="metric-value money">${money(toManifest)}</div></div><div class="metric"><div class="metric-label">CT-e acima do pago</div><div class="metric-value money">${money(overManifested)}</div></div></div><section class="card"><div class="card-header"><div><h2>Confer√™ncia por per√≠odo de atividade</h2><p>O valor fiscal √© somado uma vez por CT-e; notas manifestadas dentro do mesmo CT-e n√£o duplicam o valor.</p></div><span class="badge gray">${activities.length} atividade(s)</span></div><div class="toolbar"><input id="reconciliation-search" type="search" value="${e(query)}" placeholder="Buscar placa ou motorista" aria-label="Buscar placa ou motorista"><span class="period-caption">${activities.length} atividade(s) nesta sele√ß√£o</span></div>${activities.length?`<div class="table-wrap"><table class="reconciliation-table"><thead><tr><th>PLACA / MOTORISTA</th><th>IN√çCIO E FIM DAS ATIVIDADES</th><th class="num">CT-ES / VALOR MANIFESTADO</th><th class="num">TOTAL PAGO</th><th>SITUA√á√ÉO FISCAL</th><th>A√á√ïES</th></tr></thead><tbody>${rows}</tbody></table></div>`:`<div class="empty"><h3>${all.length?'Nenhuma placa encontrada':'Ainda n√£o h√° caminh√µes cadastrados'}</h3><p>${all.length?'Tente buscar por outra placa ou motorista.':'Cadastre uma placa e envie CT-es para iniciar o encontro de contas.'}</p></div>`}<div class="card-footer"><span>Os valores consideram todas as fazendas e faturas ligadas ao per√≠odo da placa.</span><strong>Falta manifestar: ${money(toManifest)}</strong></div></section>`;
}
